function BeginnerAssembleBossRankRoot:FreshToggleTab()
	local toggleData = {}
	local config = checkTable(Config)
	for i, v in pairs(config) do
		table.insert(toggleData,{
			index = checkNumber(i),
			text = v.text,
			checkFunc = function()
				return true
			end,
			func = function()
				self.myRankType = checkInt(i)
				BeginnerUtils.GetBeginnerMgr():SetChooseStep(self.myRankType)
				GameUtils.ReloadData(self.LoopView, 0)
				self:FreshListByListType()
			end
		})
	end
	self._toggleData = toggleData
	---@type CommonTabToggleUp
	local env = CfUtils.GetLuaScr(self.CommonTabToggleUp.gameObject, CommonTabToggleUpEnvPath)
	if isNull(env) then return end
	env:FillToggles(self._toggleData, self.myRankType)
	--end
end
function BeginnerAssembleBossRankRoot:FreshListByListType()
	self:RefreshShow()
