function BeginnerAssembleBossRankRoot:RefreshShow()
	self.data = self.rankData[tostring(self.myRankType)]
	self:RefreshUI()
end

function BeginnerAssembleBossRankRoot:InitData()
	self:FreshToggleTab()
	self:RefreshShow()
	self:SetTimeShow()
end

function BeginnerAssembleBossRankRoot:SetTimeShow()
	self:RemoveTimer()
	local dailyTime = self.dojo:GetDailyRefreshTime()
	local curTime = GameUtils.GetServerTime() or os.time()
	local remainTime = dailyTime - curTime
	if remainTime >= 0 then
		CfUtils.FillText(self.TxtTimeTotal,CfUtils.GetTimeHMS2(checkNumber(remainTime)))
		self.Timer = CS.Engine.Modules.CDTimerModule.GetInstance():AddCD(1, function(count, id)
			if count > 0 then
				CfUtils.FillText(self.TxtTimeTotal,CfUtils.GetTimeHMS2(checkNumber(count)))
			else
				CfUtils.FillText(self.TxtTimeTotal,CfUtils.GetTimeHMS2(0))
				self:RemoveTimer()
			end
		end, remainTime, false, true)
	else
		CfUtils.FillText(self.TxtTimeTotal,CfUtils.GetTimeHMS2(0))
	end
end

function BeginnerAssembleBossRankRoot:RemoveTimer()
	if self.Timer then
		CS.Engine.Modules.CDTimerModule.GetInstance():RemoveCD(self.Timer)
		self.Timer = nil
	end
end
