function BeginnerAssembleBossRankRoot:OnGetItemByIndex(listView, index)
	local luaIndex = index + 1
	local cellData = self.data.rank[luaIndex]
	local cell = listView:NewListViewItem("Cell")
	---@type CommonRankRootCell
	local scr = CfUtils.GetLuaScr(cell, "Game.Behaviours.CommonRankRootCell")
	scr:SetIgnoreClick(true)
	scr:Refresh(cellData, luaIndex, self.entryCtrl,1)
	return cell
end

function BeginnerAssembleBossRankRoot:RefreshRankList()
	local showCount = table.count(self.data.rank)
	if not self.LoopView.IsListViewInit then
		self.LoopView:InitListView(showCount, Bind(self, self.OnGetItemByIndex))
	else
		GameUtils.ReloadData(self.LoopView, showCount)
	end
end

function BeginnerAssembleBossRankRoot:RefreshMyRank()
	local myRankInfo = {
		hurt = self.data.myScore,
		ranking = self.data.myRank,
		type = 1,
	}
	self.data.playerRank = myRankInfo
	self._myRankScr:SetIgnoreClick(true)
	self._myRankScr:RefreshBeginnerBossMyCell(self.data, self.entryCtrl)
end

function BeginnerAssembleBossRankRoot:RefreshUI()
	local isEmpty = next(self.data.rank) == nil
	CfUtils.SetActive(self.LayoutListAndMyselef, not isEmpty)
	CfUtils.SetActive(self.EmptyNode, false)
	if isEmpty then
		CfUtils.SetActive(self.EmptyNode, true)
		return
	end
	
	self:RefreshRankList()
	self:RefreshMyRank()
end
